class Widget {};

// Demonstrates reference counting behavior
void shared_ptr_semantics() {
    auto sp1 = std::make_shared<Widget>();
    // sp1.use_count() is 1

    // Copying increments the reference count
    auto sp2 = sp1; // Atomic increment
    // sp1.use_count() is 2, sp2.use_count() is 2

    {
        // Another copy in a new scope
        auto sp3 = sp1; // Atomic increment
        // sp1.use_count() is 3
    } // sp3 goes out of scope, atomic decrement
    // sp1.use_count() is 2

    // Moving is faster: no change to reference count
    auto sp4 = std::move(sp2); // No atomic operation on ref count
    // sp1.use_count() is 2, sp4.use_count() is 2
    // sp2 is now nullptr
}
